import pandas as pd
import numpy as np

before = pd.read_csv('before.csv')
after = pd.read_csv('after.csv')

# Exclude id
cols = [c for c in before.columns if c != 'id']
changed = {}
for col in cols:
    if not np.allclose(before[col].values, after[col].values, rtol=1e-9, atol=1e-12):
        changed[col] = True
    else:
        changed[col] = False
print('Changed columns:', [c for c, v in changed.items() if v])
print('Unchanged columns:', [c for c, v in changed.items() if not v])

# For changed columns, examine relationship
for col in cols:
    if changed[col]:
        b = before[col].values
        a = after[col].values
        # Avoid zeros for ratio
        mask = b != 0
        if np.any(mask):
            ratio = a[mask] / b[mask]
            # Check if ratio constant
            if np.allclose(ratio, ratio[0], rtol=1e-9, atol=1e-12):
                print(f'{col}: after = {ratio[0]} * before (constant multiplier)')
            else:
                # Check if after = before * something like log, sqrt, square
                # Try log: after = log(before) maybe?
                # Compute log(before) and compare
                logb = np.log(b)
                if np.allclose(logb, a, rtol=1e-9, atol=1e-12):
                    print(f'{col}: after = log(before)')
                else:
                    sqrtb = np.sqrt(b)
                    if np.allclose(sqrtb, a, rtol=1e-9, atol=1e-12):
                        print(f'{col}: after = sqrt(before)')
                    else:
                        sqrb = b ** 2
                        if np.allclose(sqrb, a, rtol=1e-9, atol=1e-12):
                            print(f'{col}: after = square(before)')
                        else:
                            # Maybe after = before * constant? already checked
                            # Could be after = before + constant?
                            diff = a - b
                            if np.allclose(diff, diff[0], rtol=1e-9, atol=1e-12):
                                print(f'{col}: after = before + {diff[0]} (constant add)')
                            else:
                                print(f'{col}: unknown transformation')
        else:
            print(f'{col}: before all zeros?')
